"""Execute real modal functions and handlers in an isolated Node DOM simulation."""
import shutil
import subprocess
from pathlib import Path
import pytest

INDEX = Path(__file__).with_name("index.html")
NODE = shutil.which("node")
NODE_HARNESS = '\nconst fs = require(\'node:fs\'), vm = require(\'node:vm\'), assert = require(\'node:assert/strict\');\nconst html = fs.readFileSync(process.argv.at(-1), \'utf8\');\nlet count = 0;\nfunction check(value, message) { assert.ok(value, message); count++; }\nfunction source(name) {\n  const start = html.search(new RegExp(\'^        (?:async )?function \'+name+\'\\\\(\', \'m\'));\n  assert.ok(start >= 0, \'missing \'+name);\n  const tail = html.slice(start), next = tail.slice(1).search(/\\n        (?:async )?function /);\n  return next < 0 ? tail : tail.slice(0, next + 1);\n}\nfunction setup() {\n  const map = {}, timers = [], focusCalls = [];\n  const doc = {activeElement:null,getElementById:id=>map[id] || null};\n  class Element {\n    constructor(id, parent=null, type=\'button\') {\n      this.id=id; this.parentElement=parent; this.type=type; this.tabIndex=0;\n      this.disabled=false; this.isConnected=true; this.visible=true;\n      this.attrs={}; this.style={}; this.controls=[]; this.value=\'\'; this.textContent=\'\'; this.innerHTML=\'\';\n      const classes=new Set(); this.classList={add:x=>classes.add(x),remove:x=>classes.delete(x),contains:x=>classes.has(x)};\n      map[id]=this;\n    }\n    setAttribute(k,v){this.attrs[k]=v;if(k===\'tabindex\')this.tabIndex=Number(v);}\n    hasAttribute(k){return k in this.attrs;}\n    contains(el){for(let p=el;p;p=p.parentElement)if(p===this)return true;return false;}\n    closest(){for(let p=this;p;p=p.parentElement)if(p.classList.contains(\'hidden\') || p.hasAttribute(\'hidden\') || p.hasAttribute(\'inert\'))return p;return null;}\n    getClientRects(){return this.isConnected&&this.visible&&!this.closest()?[{}]:[];}\n    querySelectorAll(){return this.controls;}\n    focus(){focusCalls.push(this.id);doc.activeElement=this;}\n  }\n  const outer = new Element(\'trigger\');doc.activeElement=outer;\n  const ids=[\'authModal\',\'applyModal\',\'customTopicModal\',\'passportModal\',\'normControlModal\',\'galeShapleyModal\',\'rejectReasonModal\',\'checkpointReviewModal\',\'checkpointHistoryModal\'];\n  for(const id of ids){const m=new Element(id);m.classList.add(\'hidden\');m.controls=[new Element(id+\'First\',m),new Element(id+\'Last\',m)];}\n  new Element(\'historyModalTitle\',map.checkpointHistoryModal,\'heading\');new Element(\'historyModalList\',map.checkpointHistoryModal,\'div\');\n  new Element(\'reviewModalSubtitle\',map.checkpointReviewModal,\'div\');new Element(\'reviewModalCheckpointId\',map.checkpointReviewModal,\'hidden\');\n  new Element(\'reviewModalComment\',map.checkpointReviewModal,\'textarea\');\n  const hiddenInput=map.reviewModalCheckpointId;hiddenInput.tabIndex=0;\n  map.checkpointReviewModal.controls.unshift(hiddenInput);\n  const ctx={document:doc,setTimeout:fn=>{timers.push(fn);},apiFetch:async()=>({json:async()=>[]}),escapeHtml:x=>String(x)};\n  for(const [name,id] of Object.entries({closeAuthModal:\'authModal\',closeApplyModal:\'applyModal\',closeCustomTopicModal:\'customTopicModal\',closePassportModal:\'passportModal\',closeNormControlModal:\'normControlModal\',closeGaleShapleyModal:\'galeShapleyModal\',closeRejectReasonModal:\'rejectReasonModal\'}))ctx[name]=()=>ctx.notifyModalClose(map[id]);\n  vm.createContext(ctx);\n  const start=html.indexOf(\'        let activeModalTrigger = null;\'),end=html.indexOf(\'        function openAuthModal(\',start);\n  vm.runInContext(html.slice(start,end)+\'\\n\'+[\'openCheckpointHistory\',\'closeHistoryModal\',\'openReviewRevisionModal\',\'closeReviewModal\'].map(source).join(\'\\n\'),ctx);\n  function key(name,shift=false){const e={key:name,shiftKey:shift,prevented:false,preventDefault(){this.prevented=true;}};ctx.handleModalKeydown(e);return e;}\n  return {ctx,map,doc,outer,focusCalls,Element,key,flush:()=>{while(timers.length)timers.shift()();},current:()=>vm.runInContext(\'currentOpenModal && currentOpenModal.id\',ctx)};\n}\n(async()=>{\n  let t=setup();await t.ctx.openCheckpointHistory(7,\'History title\');t.flush();\n  check(t.current()===\'checkpointHistoryModal\',\'history tracked\');\n  check(t.doc.activeElement===t.map.checkpointHistoryModal.controls[0],\'history gets focus\');\n  check(t.map.historyModalTitle.textContent===\'История версий: History title\',\'history title stays text\');\n  check(t.key(\'Escape\').prevented,\'escape consumed\');\n  check(t.current()===null&&t.doc.activeElement===t.outer,\'history closes and restores focus\');\n\n  t=setup();t.ctx.openReviewRevisionModal(\'7\',"\'*alert(1)*\'",\'Student\');t.flush();\n  check(t.current()===\'checkpointReviewModal\',\'review tracked\');\n  check(t.doc.activeElement.id===\'checkpointReviewModalFirst\',\'hidden input skipped\');\n  check(t.map.reviewModalCheckpointId.value===\'7\',\'review ID preserved\');\n  check(t.map.reviewModalSubtitle.textContent.includes("\'*alert(1)*\'"),\'review title remains text\');\n  t.map.checkpointReviewModal.controls.at(-1).focus();\n  check(t.key(\'Tab\').prevented&&t.doc.activeElement.id===\'checkpointReviewModalFirst\',\'Tab wraps\');\n  check(t.key(\'Tab\',true).prevented&&t.doc.activeElement.id===\'checkpointReviewModalLast\',\'Shift Tab wraps\');\n  t.outer.focus();check(t.key(\'Tab\').prevented&&t.doc.activeElement.id===\'checkpointReviewModalFirst\',\'escaped focus returns inside\');\n  t.outer.focus();check(t.key(\'Tab\',true).prevented&&t.doc.activeElement.id===\'checkpointReviewModalLast\',\'reverse escaped focus returns inside\');\n  t.key(\'Escape\');check(t.doc.activeElement===t.outer&&t.current()===null,\'review restores trigger\');\n  check(!t.key(\'Escape\').prevented,\'Escape without modal unchanged\');\n\n  t=setup();t.ctx.notifyModalOpen(t.map.authModal);t.flush();const nestedTrigger=t.map.authModal.controls[1];nestedTrigger.focus();\n  t.ctx.openReviewRevisionModal(8,\'Title\',\'Name\');t.flush();t.key(\'Escape\');\n  check(t.current()===\'authModal\',\'Escape closes top modal only\');\n  check(!t.map.authModal.classList.contains(\'hidden\'),\'parent dialog remains open\');\n  check(t.doc.activeElement===nestedTrigger,\'nested trigger restored\');\n  t.ctx.notifyModalClose(t.map.applyModal);check(t.doc.activeElement===nestedTrigger&&t.current()===\'authModal\',\'closing unrelated hidden modal does not steal focus\');\n  t.key(\'Escape\');check(t.doc.activeElement===t.outer&&t.current()===null,\'parent restores original trigger\');\n\n  t=setup();t.ctx.notifyModalOpen(t.map.authModal);t.ctx.notifyModalClose(t.map.authModal);const before=t.focusCalls.length;t.flush();\n  check(t.doc.activeElement===t.outer&&t.focusCalls.length===before,\'delayed focus cannot target closed dialog\');\n  t=setup();t.ctx.notifyModalOpen(t.map.authModal);t.flush();t.ctx.notifyModalOpen(t.map.authModal);t.flush();t.ctx.notifyModalClose(t.map.authModal);\n  check(t.doc.activeElement===t.outer&&t.current()===null,\'repeat open preserves original trigger\');\n  t=setup();const empty=new t.Element(\'emptyModal\');empty.classList.add(\'hidden\');t.ctx.notifyModalOpen(empty);t.flush();\n  check(t.doc.activeElement===empty&&empty.attrs.tabindex===\'-1\',\'empty dialog fallback focus\');\n  check(t.key(\'Tab\').prevented&&t.doc.activeElement===empty,\'empty dialog traps Tab\');\n  t.key(\'Escape\');check(t.doc.activeElement===t.outer,\'unknown dialog closes safely\');\n\n  t=setup();const m=t.map.authModal;const disabled=new t.Element(\'disabled\',m);disabled.disabled=true;const negative=new t.Element(\'negative\',m);negative.tabIndex=-1;const hidden=new t.Element(\'hidden\',m);hidden.visible=false;m.controls.unshift(disabled,negative,hidden);\n  t.ctx.notifyModalOpen(m);t.flush();check(t.doc.activeElement.id===\'authModalFirst\',\'ineligible controls excluded\');\n  check(m.attrs.role===\'dialog\'&&m.attrs[\'aria-modal\']===\'true\',\'dialog semantics applied\');\n  t.outer.isConnected=false;t.ctx.notifyModalClose(m);check(t.current()===null,\'removed trigger does not break close\');\n\n  for(const [id,title] of [[\'checkpointReviewModal\',\'reviewModalTitle\'],[\'checkpointHistoryModal\',\'historyModalTitle\']]){\n    const tag=html.match(new RegExp(\'<div id="\'+id+\'"([^>]*)>\'))[1];\n    check(tag.includes(\'role="dialog"\')&&tag.includes(\'aria-labelledby="\'+title+\'"\'),\'named dialog \'+id);\n    check(html.includes(\'id="\'+title+\'"\'),\'existing dialog heading \'+title);\n  }\n  const historyButtons=html.split(\'\\n\').filter(x=>x.includes(\'<button\')&&x.includes(\'onclick="openCheckpointHistory(\'));\n  check(historyButtons.length===2,\'both history buttons retained\');\n  const eStart=html.indexOf(\'        function escapeHtml(\'),eEnd=html.indexOf(\'        // Немедленная\',eStart);\n  for(const line of historyButtons){\n    let called=null;const dangerous="\'*alert(1)*\'\\" <tag> &";\n    const ctx={c:{id:7},cleanTitle:dangerous,alert:()=>{throw Error(\'injected\')},openCheckpointHistory:(...args)=>{called=args;}};vm.createContext(ctx);vm.runInContext(html.slice(eStart,eEnd),ctx);\n    const rendered=vm.runInContext(\'`\'+line.trim()+\'`\',ctx),attrs={};\n    for(const match of rendered.matchAll(/([\\w-]+)="([^"]*)"/g))attrs[match[1]]=match[2].replace(/&(amp|lt|gt|quot|#39);/g,(_,k)=>({amp:\'&\',lt:\'<\',gt:\'>\',quot:\'"\',\'#39\':"\'"})[k]);\n    ctx.button={dataset:{checkpointId:attrs[\'data-checkpoint-id\'],historyTitle:attrs[\'data-history-title\']}};\n    vm.runInContext(\'(function(){\'+attrs.onclick+\'}).call(button)\',ctx);\n    check(called[0]===\'7\'&&called[1]===dangerous,\'history handler preserves dangerous title as data\');\n  }\n  const scripts=[...html.matchAll(/<script\\b([^>]*)>([\\s\\S]*?)<\\/script\\s*>/gi)].filter(x=>!x[1].includes(\'src=\')&&x[2].trim());\n  for(const script of scripts)new vm.Script(script[2]);check(scripts.length===4,\'four inline scripts compile\');\n  console.log(count+\' behavioral and markup checks passed; browser behavior simulated in Node.\');\n})().catch(e=>{console.error(e);process.exitCode=1;});\n'

def test_modal_history_review_focus_keyboard_and_safe_titles():
    if NODE is None:
        pytest.skip("Node is required for modal behavior regression")
    result = subprocess.run([NODE, "-e", NODE_HARNESS, str(INDEX)],
                            capture_output=True, text=True, encoding="utf-8", timeout=20)
    assert result.returncode == 0, result.stdout + result.stderr
